# ddogs/tools/Build-AreteRewardsFix.ps1 - AO-Universe Arete reveal pass: #22 Janos rewards, #11a Vaughn bribe, reward stack counts. Called by Build-AreteMarket.ps1.
# Real: JNSR 11266 xp, +1 ICC Commendations (stat 695), +1 Freelancers Inc. Tokens (stat 696), an item (Randy's screenshot); WDK2 Recharger x50 / Stim x25 (guide #2);
#   bribe = 15000 credits through the trade window when Vaughn asks for the ID and you say you're rich, he files a false ID (guide #11a).
# Guessed: JNSR credits 1000 (guide only says "credits"); the item is the Freelancers Inc. Token 303237; the ICC HQ Access Terminal is a reply on Vaughn
#   that teleports to the ICC Shuttleport next to Brandon Thorn (4582 934.9 24.8 762.0). Needs the Reward.Stats / item Count engine change (same commit).
param([string]$GameData = (Join-Path $PSScriptRoot '..\..\AORebirth\GameData'))
$ErrorActionPreference = 'Stop'
Remove-TypeData System.Array -ErrorAction SilentlyContinue
$u = [Text.UTF8Encoding]::new($false)
$gd = [IO.Path]::GetFullPath($GameData)
$qpath = Join-Path $gd 'Quests.json'
$q = @(); foreach ($x in (ConvertFrom-Json -InputObject ([IO.File]::ReadAllText($qpath, $u)))) { if ($x.Hash -ne 'VHBR') { $q += $x } }
if ($q | Where-Object { $_.MissionBit -eq 710 }) { throw 'bit 710 taken' }
foreach ($x in $q) {
  if ($x.Hash -eq 'JNSR') { $x.Reward = [pscustomobject]@{ Hash='RNSR'; Credits=1000; Xp=11266; Stats=[ordered]@{ '695'=1; '696'=1 }
      Records=@(,@([pscustomobject]@{ Id=303237; HighId=303237; Name='Freelancers Inc. Token'; Quality=1; Count=1 })) } }
  if ($x.Hash -eq 'WDK2') { $x.Reward.Records = @(,@(
      [pscustomobject]@{ Id=291082; HighId=291082; Name='Health and Nano Recharger'; Quality=1; Count=50 },
      [pscustomobject]@{ Id=291043; HighId=291043; Name='Health and Nano Stim'; Quality=1; Count=25 })) }
}
$q += [pscustomobject]@{ Hash='VHBR'; Name='Bribe Vaughn Hammond'; QasInstance=920180; Scope='Solo'; Action='TargetNpc'; Summary='Pay Vaughn Hammond 15000 credits to overlook your missing ID'
  Objective=[pscustomobject]@{ Count=$null; Npc='AVHA'; SpecItem=$null; WorldItem=$null }; Flags='NoCash'; MissionBit=710; NextStep=$null; Reward=[pscustomobject]@{ Hash='RVHB'; Credits=0; Xp=0; Records=$null } }
[IO.File]::WriteAllText($qpath, ((ConvertTo-Json -InputObject @($q) -Depth 8) -replace "`r`n", "`n") + "`n", $u)
$go = '{teleport 4582 934.9 24.8 762.0}'
$v = [ordered]@{ Notes = 'Vaughn Hammond (3369x828). #11b: trade the Identification Card (AVHR). #11a: say you are rich, trade 15000 credits, false ID filed (VHBR). Access Terminal as a reply: guessed. Generated by ddogs/tools/Build-NewbieQuests.ps1, patched by Build-AreteRewardsFix.ps1.'
  Npcs = @('SimpleChar:78E0FC73')
  Openers = @( [ordered]@{ If = @('HasCompletedQuest AVHR'); Say = 'cleared' }, [ordered]@{ If = @('HasCompletedQuest VHBR'); Say = 'cleared' }, [ordered]@{ If = @('HasQuest AVHR'); Say = 'card' }, [ordered]@{ Say = 'hello' } )
  Replies = [ordered]@{
    rich = [ordered]@{ Text = 'I don''t have an ID card. But I''m rich.'; If = @('!HasCompletedQuest VHBR'); Goto = 'price' }
    richer = [ordered]@{ Text = 'Really rich.'; Goto = 'deal' }
    termA = [ordered]@{ Text = 'Use the ICC HQ Access Terminal. Yes.'; If = @('HasCompletedQuest AVHR'); Goto = 'go' }
    termB = [ordered]@{ Text = 'Use the ICC HQ Access Terminal. Yes.'; If = @('HasCompletedQuest VHBR'); Goto = 'go' }
    nothing = [ordered]@{ Text = 'Nothing right now, thanks.'; Goto = 'nothing' } }
  Lines = [ordered]@{
    hello = [ordered]@{ Text = @('{delay 1}Vaughn Hammond. Nobody goes through that gate without an Identification Card. Let''s see yours.'); Replies = @('rich','nothing') }
    card = [ordered]@{ Text = 'The Identification Card. Trade it.{opentrade}'; Replies = @('rich','nothing') }
    price = [ordered]@{ Text = 'Rich, you say? Everybody on this rock says that.'; Replies = @('richer','nothing') }
    deal = [ordered]@{ Text = 'Hm. 15000 credits and I''ll overlook the missing ID. Put it in the window.{opentrade}' }
    uploaded = [ordered]@{ Text = @('{completequest AVHR}', 'Uploaded. The ICC HQ Access Terminal will take you through whenever you are ready.'); Replies = @('termA','nothing') }
    bribed = [ordered]@{ Text = @('{givequest VHBR}', '{completequest VHBR}', 'Impressive. I''ve filed an ID for you and uploaded it to your NCU. The ICC HQ Access Terminal will take you through.'); Replies = @('termB','nothing') }
    cleared = [ordered]@{ Text = 'Your ID checks out. The ICC HQ Access Terminal is right there.'; Replies = @('termA','termB','nothing') }
    go = [ordered]@{ Text = "Welcome to Rubi-Ka Mainland.$go" }
    nothing = [ordered]@{ Text = 'Safe travels.{close}' } }
  Trades = [ordered]@{
    card = [ordered]@{ If = @('HasQuest AVHR'); Items = @([ordered]@{ Hash = 'QIDC'; Count = 1 }); Goto = 'uploaded' }
    bribe = [ordered]@{ If = @('!HasCompletedQuest VHBR','!HasCompletedQuest AVHR'); Credits = 15000; Goto = 'bribed' } } }
[IO.File]::WriteAllText((Join-Path $gd 'Knubot\VaughnHammond.json'), (($v | ConvertTo-Json -Depth 8) -replace "`r`n", "`n") + "`n", $u)
'rewards fix written'